mapper.select:
SELECT  FROM ad_reconciliation_task
WHERE advertiser_id=#{advertiserId} AND task_id=#{taskId}
FOR UPDATE

SELECT d.budget_date,d.fence,d.report_version,d.report_json::text,d.observed_at FROM ad_reconciliation_day d
JOIN ad_reconciliation_task t USING(task_id) WHERE t.advertiser_id=#{advertiserId} AND t.task_id=#{taskId}
ORDER BY d.budget_date LIMIT 31
